"use client";

import React, { useState } from "react";
import { AlertCircle } from "lucide-react";

export function ProductStockStatus() {
  const [stock, setStock] = useState(4);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-4 rounded-xl shadow-lg select-none font-sans text-foreground">
      <div className="flex items-center justify-between text-xs mb-2">
        <span className="text-muted-foreground/60">Inventory Capacity</span>
        <span className={`font-bold ${stock < 5 ? "text-amber-400" : "text-emerald-400"}`}>
          {stock} items remaining
        </span>
      </div>
      <div className="h-1.5 bg-secondary/40 rounded-full overflow-hidden">
        <div className="h-full bg-gradient-to-r from-amber-500 to-rose-500 rounded-full" style={{ width: `${(stock / 20) * 100}%` }} />
      </div>
      {stock < 5 && (
        <span className="block text-[9px] uppercase font-bold text-amber-400 mt-2 flex items-center gap-0.5">
          <AlertCircle className="w-3 h-3" /> Low Stock Level Warning
        </span>
      )}
    </div>
  );
}
